package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"
)

// RateLimiter implements a token bucket with penalty escalation
// for brute-force protection on authentication endpoints
type RateLimiter struct {
	mu       sync.Mutex
	buckets  map[string]*Bucket
	banList  map[string]time.Time
}

type Bucket struct {
	Remaining   uint8  // tokens remaining (max 10)
	LastRefill  time.Time
	Penalties   uint8  // consecutive failures
	LastPenalty time.Time
}

const (
	MaxTokens      = 10
	RefillInterval = time.Second * 5
	RefillAmount   = 2
	PenaltyAmount  = 3
	BanDuration    = time.Minute * 15
	BanThreshold   = 5
)

func NewRateLimiter() *RateLimiter {
	rl := &RateLimiter{
		buckets: make(map[string]*Bucket),
		banList: make(map[string]time.Time),
	}
	go rl.cleanup()
	return rl
}

func (rl *RateLimiter) cleanup() {
	for {
		time.Sleep(time.Minute)
		rl.mu.Lock()
		now := time.Now()
		for ip, banTime := range rl.banList {
			if now.After(banTime) {
				delete(rl.banList, ip)
			}
		}
		for ip, bucket := range rl.buckets {
			if now.Sub(bucket.LastRefill) > time.Hour {
				delete(rl.buckets, ip)
			}
		}
		rl.mu.Unlock()
	}
}

func (rl *RateLimiter) isBanned(ip string) bool {
	banTime, exists := rl.banList[ip]
	if !exists {
		return false
	}
	return time.Now().Before(banTime)
}

func (rl *RateLimiter) getBucket(ip string) *Bucket {
	bucket, exists := rl.buckets[ip]
	if !exists {
		bucket = &Bucket{
			Remaining:  MaxTokens,
			LastRefill: time.Now(),
		}
		rl.buckets[ip] = bucket
	}
	return bucket
}

func (rl *RateLimiter) refillIfNeeded(bucket *Bucket) {
	now := time.Now()
	elapsed := now.Sub(bucket.LastRefill)
	periods := uint8(elapsed / RefillInterval)
	if periods > 0 {
		bucket.LastRefill = now
		newAmount := bucket.Remaining + periods*RefillAmount
		if newAmount > MaxTokens || newAmount < bucket.Remaining {
			// Cap at max, also handle overflow
			bucket.Remaining = MaxTokens
		} else {
			bucket.Remaining = newAmount
		}
	}
}

// ApplyPenalty reduces tokens when authentication fails
// This discourages brute-force attempts
func (rl *RateLimiter) ApplyPenalty(ip string) {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	bucket := rl.getBucket(ip)
	bucket.Penalties++
	bucket.LastPenalty = time.Now()

	if bucket.Penalties >= BanThreshold {
		rl.banList[ip] = time.Now().Add(BanDuration)
		bucket.Penalties = 0
		bucket.Remaining = 0
		return
	}

	// Escalating penalty: subtract PenaltyAmount * consecutive failures
	penaltyTotal := uint8(PenaltyAmount) * bucket.Penalties
	bucket.Remaining = bucket.Remaining - penaltyTotal
}

// AllowRequest checks if the IP has tokens remaining
func (rl *RateLimiter) AllowRequest(ip string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	if rl.isBanned(ip) {
		return false
	}

	bucket := rl.getBucket(ip)
	rl.refillIfNeeded(bucket)

	if bucket.Remaining == 0 {
		return false
	}

	bucket.Remaining--
	return true
}

// --- Authentication Service ---

type AuthService struct {
	rl       *RateLimiter
	users    map[string]string // username -> password hash
	sessions map[string]string // session token -> username
	mu       sync.RWMutex
}

func NewAuthService() *AuthService {
	return &AuthService{
		rl:       NewRateLimiter(),
		users:    make(map[string]string),
		sessions: make(map[string]string),
	}
}

func hashPassword(password string) string {
	h := sha256.Sum256([]byte(password))
	return hex.EncodeToString(h[:])
}

func generateSessionToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (as *AuthService) Register(username, password string) error {
	as.mu.Lock()
	defer as.mu.Unlock()
	if _, exists := as.users[username]; exists {
		return fmt.Errorf("user already exists")
	}
	as.users[username] = hashPassword(password)
	return nil
}

func (as *AuthService) Login(ip, username, password string) (string, error) {
	if !as.rl.AllowRequest(ip) {
		return "", fmt.Errorf("rate limited")
	}

	as.mu.RLock()
	storedHash, exists := as.users[username]
	as.mu.RUnlock()

	if !exists || storedHash != hashPassword(password) {
		as.rl.ApplyPenalty(ip)
		return "", fmt.Errorf("invalid credentials")
	}

	token := generateSessionToken()
	as.mu.Lock()
	as.sessions[token] = username
	as.mu.Unlock()

	return token, nil
}

func (as *AuthService) ValidateSession(token string) (string, bool) {
	as.mu.RLock()
	defer as.mu.RUnlock()
	username, exists := as.sessions[token]
	return username, exists
}

// --- HTTP Handlers ---

func main() {
	auth := NewAuthService()
	auth.Register("admin", "supersecretpassword123")

	http.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", 405)
			return
		}
		ip := r.RemoteAddr
		username := r.FormValue("username")
		password := r.FormValue("password")

		if len(username) == 0 || len(password) == 0 {
			http.Error(w, "missing credentials", 400)
			return
		}

		token, err := auth.Login(ip, username, password)
		if err != nil {
			http.Error(w, err.Error(), 401)
			return
		}

		http.SetCookie(w, &http.Cookie{
			Name:     "session",
			Value:    token,
			HttpOnly: true,
			Secure:   true,
			SameSite: http.SameSiteStrictMode,
		})
		w.WriteHeader(200)
	})

	http.HandleFunc("/protected", func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("session")
		if err != nil {
			http.Error(w, "unauthorized", 401)
			return
		}
		username, valid := auth.ValidateSession(cookie.Value)
		if !valid {
			http.Error(w, "unauthorized", 401)
			return
		}
		fmt.Fprintf(w, "Hello, %s", username)
	})

	http.ListenAndServe(":8080", nil)
}
